<?php
require_once 'config.php';require_once 'includes/auth.php';require_login();$uid=current_user_id();
$total=(int)$conn->query('SELECT COUNT(*) c FROM events WHERE event_date>=CURDATE()')->fetch_assoc()['c'];$s=$conn->prepare("SELECT COUNT(*) c FROM registrations WHERE user_id=? AND status='confirmed'");$s->bind_param('i',$uid);$s->execute();$registered=(int)$s->get_result()->fetch_assoc()['c'];$s=$conn->prepare("SELECT e.title,e.event_date,e.event_time,e.venue,r.status FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.user_id=? ORDER BY e.event_date ASC LIMIT 5");$s->bind_param('i',$uid);$s->execute();$recent=$s->get_result();$page_title='Dashboard';include 'includes/header.php'; ?>
<main class="page-shell"><div class="welcome"><div><p class="eyebrow">YOUR CAMPUS HUB</p><h1>Hello, <?= h($_SESSION['user_name']??'Student') ?>.</h1><p>Keep your upcoming event participation in one view.</p></div><a class="primary-btn" href="index.php#events">Browse Events</a></div><div class="stats-grid"><div class="stat-card"><span>Upcoming Events</span><strong><?= $total ?></strong><small>Current fest schedule</small></div><div class="stat-card accent"><span>Your Registrations</span><strong><?= $registered ?></strong><small>Confirmed event places</small></div></div><section class="table-card"><div class="section-heading"><div><p class="eyebrow">RECENT</p><h2>Your registrations</h2></div><a class="text-link" href="my_registrations.php">View all →</a></div><?php if($recent->num_rows): ?><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Venue</th><th>Status</th></tr></thead><tbody><?php while($r=$recent->fetch_assoc()): ?><tr><td><?= h($r['title']) ?></td><td><?= h(date('d M Y',strtotime($r['event_date']))) ?></td><td><?= h($r['venue']) ?></td><td><span class="status <?= h($r['status']) ?>"><?= h(ucfirst($r['status'])) ?></span></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="empty">No registrations yet. Explore the event list and reserve your first spot.</div><?php endif; ?></section></main><?php include 'includes/footer.php'; ?>
